-- Claris Growblox Autofarm v0.1.40; generated by build.mjs.
local BASE = "https://raw.githubusercontent.com/Clarissv/Claris-Growblox-Autofarm/main/releases/06b31fcd52fa3320ef18/"
local LOADER_URL = "https://raw.githubusercontent.com/Clarissv/Claris-Growblox-Autofarm/main/loader.lua"
local CACHE = "ClarisGrowblox/cache/06b31fcd52fa3320ef18"
local env = getgenv and getgenv() or _G
local previous = env.ClarisGrowbloxApp
assert(not previous or (not previous.job and previous.pending == 0),
    "Stop the running farm and wait for requests before loading the script again.")

local function checksum(source)
    -- Detect damaged cache/download bytes against the build's Adler-32 value.
    local a, b, yieldedAt = 1, 0, os.clock()
    for index = 1, #source do
        a = (a + string.byte(source, index)) % 65521
        b = (b + a) % 65521
        if index % 4096 == 0 and os.clock() - yieldedAt >= 0.006 then
            task.wait()
            yieldedAt = os.clock()
        end
    end
    return b * 65536 + a
end
local function verified(source, size, expected)
    if type(source) ~= "string" then return nil end
    source = source:gsub("\r\n", "\n")
    if #source == size and checksum(source) == expected then return source end
end
local function cachePath(name)
    return CACHE .. "/" .. (name == "main.lua" and "main.lua" or "WindUI.lua")
end
local function saveCache(name, source)
    if type(writefile) ~= "function" or type(isfolder) ~= "function" or type(makefolder) ~= "function" then return end
    pcall(function()
        for _, folder in ipairs({"ClarisGrowblox", "ClarisGrowblox/cache", CACHE}) do
            if not isfolder(folder) then makefolder(folder) end
        end
        writefile(cachePath(name), source)
    end)
end
local function beginAsset(name, size, expected)
    if type(readfile) == "function" and type(isfile) == "function" then
        local ok, source = pcall(function()
            if isfile(cachePath(name)) then return verified(readfile(cachePath(name)), size, expected) end
        end)
        if ok and source then return {done = true, source = source, cached = true} end
    end
    local request = {deadline = os.clock() + 45, name = name, size = size, expected = expected}
    task.spawn(function()
        request.result = {pcall(function() return game:HttpGet(BASE .. name) end)}
        request.done = true
    end)
    return request
end
local function awaitAsset(request, label)
    while not request.done do
        assert(os.clock() < request.deadline, "Download timed out: " .. BASE .. request.name)
        task.wait(0.05)
    end
    if not request.source then
        assert(request.result[1], "Could not download " .. BASE .. request.name .. ": " .. tostring(request.result[2]))
        request.source = verified(request.result[2], request.size, request.expected)
        assert(request.source, "Downloaded release bytes do not match: " .. request.name)
    end
    local chunk, message = loadstring(request.source, label)
    assert(chunk, message)
    if not request.cached then saveCache(request.name, request.source) end
    return chunk
end

-- Start both uncached downloads before waiting for either response.
local main = beginAsset("main.lua", 382060, 202729728)
local wind = beginAsset("vendor/WindUI.lua", 1350010, 1511812659)
local chunk = awaitAsset(main, "Claris Growblox Autofarm")
local windChunk = awaitAsset(wind, "Claris WindUI")
env.ClarisGrowbloxLoaderDebug = "Release 06b31fcd52fa3320ef18: main " .. (main.cached and "cached" or "downloaded")
    .. "; WindUI " .. (wind.cached and "cached" or "downloaded")
env.ClarisGrowbloxWindUI = windChunk()
env.ClarisGrowbloxLoaderURL = LOADER_URL
env.ClarisGrowbloxWindUIURL = BASE .. "vendor/WindUI.lua"
return chunk()
